<script setup lang="ts">
const db=useSupabaseClient(),user=useSupabaseUser(),given=ref(''),family=ref(''),error=ref(''),busy=ref(false),status=ref('')
onMounted(async()=>{const {data:{user:u}}=await db.auth.getUser();if(!u){await navigateTo('/login');return}given.value=u.user_metadata?.full_name?.split(' ')[0]||'';family.value=u.user_metadata?.full_name?.split(' ').slice(1).join(' ')||'';const r=await db.from('student_account_requests').select('status').eq('user_id',u.id).maybeSingle();status.value=r.data?.status||'';if(status.value==='approved')await navigateTo('/student')})
async function submit(){error.value='';busy.value=true;const r=await db.rpc('submit_student_account_request',{p_given_name:given.value.trim(),p_family_name:family.value.trim()});busy.value=false;if(r.error){error.value=r.error.message;return}status.value=r.data||'pending'}
</script>
<template><div class="page"><div class="shell admin-section"><NuxtLink to="/dashboard">← Dashboard</NuxtLink><div class="auth"><h1>Student Verification</h1><p v-if="status==='pending'" class="notice">Your school access request is awaiting approval. Please check back later.</p><p v-else-if="status==='rejected'" class="error">Your request was declined. Contact your school administrator.</p><form v-else @submit.prevent="submit"><p>Confirm your name to request student access. Your school administrator will match your account to your existing school record.</p><label class="field"><span>First name</span><input v-model="given" required maxlength="100"></label><label class="field"><span>Last name</span><input v-model="family" required maxlength="100"></label><p v-if="error" class="error">{{error}}</p><button class="btn" :disabled="busy">{{busy?'Submitting…':'Request School Access'}}</button></form></div></div></div></template>
